@cached_property
def image_orient_patient(self):
    """
    Note that this is _not_ LR flipped
    """
    try:
        iop = self.shared.PlaneOrientationSequence[0].ImageOrientationPatient
    except AttributeError:
        try:
            iop = self.frames[0].PlaneOrientationSequence[0].ImageOrientationPatient
        except AttributeError:
            raise WrapperError('Not enough information for image_orient_patient')
    if iop is None:
        return None
    iop = np.array(list(map(float, iop)))
    return np.array(iop).reshape(2, 3).T

def _frames_in_data_order(self):
    """Frames in the order that ``get_data()`` sorts them

    ``get_data()`` sorts frames with ``np.lexsort(self._frame_indices.T)``
    over the *DimensionIndexValues* DICOM attribute of each frame (minus
    the constant *StackID* index), so that the first frame index changes
    fastest.  Sorting on the reversed index tuples reproduces that order.
    """
    indexed_frames = [
        (tuple(map(int, frame.FrameContentSequence[0].DimensionIndexValues)), frame)
        for frame in self.frames
    ]
    return [frame for _, frame in sorted(indexed_frames, key=lambda pair: pair[0][::-1])]

@cached_property
def slice_normal(self):
    iop = self.image_orient_patient
    if iop is None:
        return None
    # iop[:, 0] is column index cosine, iop[:, 1] is row index cosine.
    # Their cross product is the DICOM image plane normal.
    normal = np.cross(iop[:, 0], iop[:, 1])
    # Frames are laid out along the third array axis in the order given
    # by their dimension indices (see ``get_data()``).  Orient the
    # normal along the actual sorted frame positions so that the affine
    # maps array indices to their DICOM patient positions.
    try:
        positions = [
            np.array(list(map(float, frame.PlanePositionSequence[0].ImagePositionPatient)))
            for frame in self._frames_in_data_order()
        ]
    except AttributeError:
        return normal
    if len(positions) > 1 and np.dot(positions[-1] - positions[0], normal) < 0:
        return -normal
    return normal

