@cached_property
def image_position(self):
    try:
        ipp = self.shared.PlanePositionSequence[0].ImagePositionPatient
    except AttributeError:
        # The position of the first frame in ``get_data()`` order, that
        # is the frame at array position (0, 0, 0, ...).  Frames may be
        # stored in any order in the object, so ``frames[0]`` is not
        # necessarily the first frame of the reconstructed array.
        try:
            frame = self._frames_in_data_order()[0]
            ipp = frame.PlanePositionSequence[0].ImagePositionPatient
        except AttributeError:
            raise WrapperError('Cannot get image position from dicom')
    if ipp is None:
        return None
    return np.array(list(map(float, ipp)))

